import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"悲回风","description":"","frontmatter":{"title":"悲回风","date":"2026-11-24T00:00:00.000Z","seq":22,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"橘颂","link":"/blogs/楚辞/橘颂.html"},"next":{"text":"远游·远游","link":"/blogs/楚辞/远游·远游.html"}},"headers":[],"relativePath":"blogs/楚辞/悲回风.md","filePath":"blogs/楚辞/悲回风.md"}'),o={name:"blogs/楚辞/悲回风.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="悲回风" tabindex="-1">悲回风 <a class="header-anchor" href="#悲回风" aria-label="Permalink to &quot;悲回风&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">悲回风之摇蕙兮，心冤结而内伤。</p><p class="poem-stanza">物有微而陨性兮，声有隐而先倡。</p><p class="poem-stanza">夫何彭咸之造思兮，暨志介而不忘！</p><p class="poem-stanza">万变其情岂可盖兮，孰虚伪之可长？</p><p class="poem-stanza">鸟兽鸣以号群兮，草苴比而不芳。</p><p class="poem-stanza">鱼葺鳞以自别兮，蛟龙隐其文章。</p><p class="poem-stanza">故荼荠不同亩兮，兰茝幽而独芳。</p><p class="poem-stanza">惟佳人之永都兮，更统世以自贶。</p><p class="poem-stanza">眇远志之所及兮，怜浮云之相羊。</p><p class="poem-stanza">介眇志之所惑兮，窃赋诗之所明。</p><p class="poem-stanza">惟佳人之独怀兮，折若椒以自处。</p><p class="poem-stanza">曾歔欷之嗟嗟兮，独隐伏而思虑。</p><p class="poem-stanza">涕泣交而凄凄兮，思不眠以至曙。</p><p class="poem-stanza">终长夜之曼曼兮，掩此哀而不去。</p><p class="poem-stanza">寤从容以周流兮，聊逍遥以自恃。</p><p class="poem-stanza">伤太息之愍怜兮，气于邑而不可止。</p><p class="poem-stanza">糺思心以为纕兮，编愁苦以为膺。</p><p class="poem-stanza">折若木以弊光兮，随飘风之所仍。</p><p class="poem-stanza">存彷佛而不见兮，心踊跃其若汤。</p><p class="poem-stanza">抚珮衽以案志兮，超惘惘而遂行。</p><p class="poem-stanza">岁曶曶其若颓兮，时亦冉冉而将至。</p><p class="poem-stanza">薠蘅槁而节离兮，芳以歇而不比。</p><p class="poem-stanza">怜思心之不可惩兮，证此言之不可聊。</p><p class="poem-stanza">宁溘死而流亡兮，不忍此心之常愁。</p><p class="poem-stanza">孤子吟而抆泪兮，放子出而不还。</p><p class="poem-stanza">孰能思而不隐兮，照彭咸之所闻。</p><p class="poem-stanza">登石峦以远望兮，路眇眇之默默。</p><p class="poem-stanza">入景响之无应兮，闻省想而不可得。</p><p class="poem-stanza">愁郁郁之无快兮，居戚戚而不可解。</p><p class="poem-stanza">心鞿羁而不开兮，气缭转而自缔。</p><p class="poem-stanza">穆眇眇之无垠兮，莽芒芒之无仪。</p><p class="poem-stanza">声有隐而相感兮，物有纯而不可为。</p><p class="poem-stanza">邈漫漫之不可量兮，缥绵绵之不可纡。</p><p class="poem-stanza">愁悄悄之常悲兮，翩冥冥之不可娱。</p><p class="poem-stanza">凌大波而流风兮，讬彭咸之所居。</p><p class="poem-stanza">上高岩之峭岸兮，处雌蜺之标颠。</p><p class="poem-stanza">据青冥而摅虹兮，遂儵忽而扪天。</p><p class="poem-stanza">吸湛露之浮源兮，漱凝霜之雰雰。</p><p class="poem-stanza">依风穴以自息兮，忽倾寤以婵媛。</p><p class="poem-stanza">冯昆仑以澂雾兮，隐渂山以清江。</p><p class="poem-stanza">惮涌湍之礚礚兮，听波声之汹汹。</p><p class="poem-stanza">纷容容之无经兮，罔芒芒之无纪。</p><p class="poem-stanza">轧洋洋之无从兮，驰委移之焉止？</p><p class="poem-stanza">漂翻翻其上下兮，翼遥遥其左右。</p><p class="poem-stanza">氾潏潏其前后兮，伴张驰之信期。</p><p class="poem-stanza">观炎气之相仍兮，窥烟液之所积。</p><p class="poem-stanza">悲霜雪之俱下兮，听潮水之相击。</p><p class="poem-stanza">借光景以往来兮，施黄棘之枉策。</p><p class="poem-stanza">求介子之所存兮，见伯夷之放迹。</p><p class="poem-stanza">心调度而弗去兮，刻著志之无适。</p><p class="poem-stanza">曰吾怨往昔之所冀兮，悼来者之悐悐。</p><p class="poem-stanza">浮江淮而入海兮，从子胥而自适。</p><p class="poem-stanza">望大河之洲渚兮，悲申徒之抗迹。</p><p class="poem-stanza">骤谏君而不听兮，重任石之何益？</p><p class="poem-stanza">心絓结而不解兮，思蹇产而不释。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
